1	#!/usr/bin/env node
2	import { spawn } from "node:child_process";
3	import { createHash } from "node:crypto";
4	import { cp, mkdir, readFile, readdir, stat, writeFile } from "node:fs/promises";
5	import { dirname, resolve } from "node:path";
6	import { fileURLToPath } from "node:url";
7	
8	const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
9	const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");
10	
11	function parseArguments(values) {
12	  const options = {};
13	  let index = 0;
14	  for (; index < values.length; index += 1) {
15	    const value = values[index];
16	    if (value === "--") break;
17	    if (!value.startsWith("--") || index + 1 >= values.length) throw new Error(`ARGUMENT_INVALID:${value}`);
18	    options[value.slice(2)] = values[index + 1];
19	    index += 1;
20	  }
21	  return { options, command: values.slice(index + 1) };
22	}
23	
24	async function fileObservation(path) {
25	  try {
26	    const bytes = await readFile(path);
27	    return { exists: true, bytes: bytes.length, sha256: sha256(bytes) };
28	  } catch (error) {
29	    if (error?.code === "ENOENT") return { exists: false, bytes: 0, sha256: null };
30	    throw error;
31	  }
32	}
33	
34	function sanitizeHostStream(bytes) {
35	  const lines = bytes.toString("utf8").split(/\r?\n/u);
36	  let redactions = 0;
37	  const sanitized = lines.map((line) => {
38	    if (!line) return line;
39	    let event;
40	    try { event = JSON.parse(line); } catch { return line; }
41	    if (event.type === "system" && ["hook_started", "hook_response"].includes(event.subtype)) {
42	      redactions += 1;
43	      return JSON.stringify({ type: event.type, subtype: event.subtype, hook_name: event.hook_name ?? null, outcome: event.outcome ?? null, payloadRedacted: true });
44	    }
45	    if (event.type === "system" && event.subtype === "init") {
46	      redactions += 1;
47	      return JSON.stringify({ type: event.type, subtype: event.subtype, cwd: event.cwd ?? null, model: event.model ?? null, permissionMode: event.permissionMode ?? null, hostInventoryRedacted: true });
48	    }
49	    return line;
50	  });
51	  return { bytes: Buffer.from(sanitized.join("\n"), "utf8"), redactions };
52	}
53	
54	async function requireAbsent(path) {
55	  try {
56	    await stat(path);
57	  } catch (error) {
58	    if (error?.code === "ENOENT") return;
59	    throw error;
60	  }
61	  throw new Error(`OUTPUT_EXISTS:${path}`);
62	}
63	
64	async function runProcess(executable, args, { cwd, input, env = process.env } = {}) {
65	  const started = performance.now();
66	  const child = spawn(executable, args, { cwd, env, windowsHide: true, stdio: ["pipe", "pipe", "pipe"] });
67	  const stdout = [];
68	  const stderr = [];
69	  child.stdout.on("data", (chunk) => stdout.push(chunk));
70	  child.stderr.on("data", (chunk) => stderr.push(chunk));
71	  if (input === undefined) child.stdin.end();
72	  else child.stdin.end(input);
73	  const result = await new Promise((completion, rejection) => {
74	    child.once("error", rejection);
75	    child.once("close", (code, signal) => completion({ code, signal }));
76	  });
77	  return {
78	    ...result,
79	    wallClockMs: Math.round(performance.now() - started),
80	    stdout: Buffer.concat(stdout),
81	    stderr: Buffer.concat(stderr),
82	  };
83	}
84	
85	async function seedOtherCard(projectRoot) {
86	  const outputPath = resolve(projectRoot, "pilot/verification.md");
87	  const current = await readFile(outputPath);
88	  const answer = {
89	    schemaVersion: 1,
90	    cardId: "another-card",
91	    verdict: "unproven",
92	    summary: "Pre-existing evaluator seed that the bookmark-storage update must preserve.",
93	    checks: [{ name: "seed remains distinguishable", outcome: "unproven", evidence: [] }],
94	    unknowns: ["This record is evaluator setup, not a fresh-agent verification claim."],
95	  };
96	  const request = Buffer.from(JSON.stringify({ currentOutputBase64: current.toString("base64"), validatedAnswer: answer }));
97	  const renderer = resolve(repositoryRoot, "domains/natural-language-pilot/targets/verify/renderer.mjs");
98	  const rendered = await runProcess(process.execPath, [renderer], { input: request });
99	  if (rendered.code !== 0) throw new Error(`SEED_RENDER_FAILED:${rendered.stderr.toString("utf8").trim()}`);
100	  await writeFile(outputPath, rendered.stdout);
101	}
102	
103	async function materialize(options) {
104	  const scene = options.scene;
105	  const projectRoot = resolve(options["project-root"] ?? "");
106	  const supported = new Set(["normal", "other-card-update", "unknown", "command-failure", "input-stale", "output-conflict", "prepare-failure-fallback", "record-response-loss-retry"]);
107	  if (!supported.has(scene)) throw new Error(`SCENE_INVALID:${scene}`);
108	  if (!options["project-root"]) throw new Error("PROJECT_ROOT_REQUIRED");
109	  await requireAbsent(projectRoot);
110	  const fixtureName = scene === "command-failure" ? "failure-project" : "project";
111	  const fixtureRoot = resolve(repositoryRoot, "fixtures/verify-v1", fixtureName);
112	  await mkdir(dirname(projectRoot), { recursive: true });
113	  await cp(fixtureRoot, projectRoot, { recursive: true, errorOnExist: true, force: false });
114	  if (scene === "unknown") {
115	    const planPath = resolve(projectRoot, "pilot/plan.md");
116	    const current = await readFile(planPath, "utf8");
117	    const changed = current.replace("fixture-plan cardId=bookmark-storage", "fixture-plan cardName=bookmark-storage");
118	    if (changed === current) throw new Error("UNKNOWN_MUTATION_ANCHOR_MISSING");
119	    await writeFile(planPath, changed, "utf8");
120	  }
121	  if (scene === "other-card-update") await seedOtherCard(projectRoot);
122	  const receipt = {
123	    schemaVersion: 1,
124	    phase: "materialized",
125	    scene,
126	    fixture: `fixtures/verify-v1/${fixtureName}`,
127	    projectRoot,
128	    output: await fileObservation(resolve(projectRoot, "pilot/verification.md")),
129	  };
130	  process.stdout.write(`${JSON.stringify(receipt)}\n`);
131	}
132	
133	async function exchangeCount(projectRoot) {
134	  const root = resolve(projectRoot, ".skill-rails-next/exchanges");
135	  try {
136	    const entries = await readdir(root, { withFileTypes: true });
137	    return entries.filter((entry) => entry.isDirectory()).length;
138	  } catch (error) {
139	    if (error?.code === "ENOENT") return 0;
140	    throw error;
141	  }
142	}
143	
144	async function injectAfterPrepare(scene, projectRoot, initialCount, timeoutMs) {
145	  if (!new Set(["input-stale", "output-conflict"]).has(scene)) return null;
146	  const deadline = Date.now() + timeoutMs;
147	  while (Date.now() < deadline) {
148	    if (await exchangeCount(projectRoot) > initialCount) {
149	      const relativePath = scene === "input-stale" ? "pilot/plan.md" : "pilot/verification.md";
150	      const path = resolve(projectRoot, relativePath);
151	      const addition = scene === "input-stale" ? "\nConcurrent plan change after prepare.\n" : "\nConcurrent terminal note.\n";
152	      const before = await fileObservation(path);
153	      const current = await readFile(path);
154	      await writeFile(path, Buffer.concat([current, Buffer.from(addition, "utf8")]));
155	      return { relativePath, before, after: await fileObservation(path) };
156	    }
157	    await new Promise((completion) => setTimeout(completion, 25));
158	  }
159	  throw new Error(`PREPARE_WATCH_TIMEOUT:${timeoutMs}`);
160	}
161	
162	async function responseLossEnvironment(scene, projectRoot) {
163	  if (scene !== "record-response-loss-retry") return { env: process.env, statePath: null };
164	  if (process.platform !== "win32") throw new Error("RESPONSE_LOSS_PROXY_REQUIRES_WINDOWS");
165	  const proxyRoot = resolve(projectRoot, ".skill-rails-next/evaluation-bin");
166	  const proxySource = resolve(repositoryRoot, "src/evaluation/node-response-loss-proxy.mjs");
167	  const proxyDestination = resolve(proxyRoot, "node-response-loss-proxy.mjs");
168	  await mkdir(proxyRoot, { recursive: true });
169	  await cp(proxySource, proxyDestination, { force: false, errorOnExist: true });
170	  const command = `@\"${process.execPath}\" \"${proxyDestination}\" %*\r\n`;
171	  await writeFile(resolve(proxyRoot, "node.cmd"), command, "utf8");
172	  return {
173	    env: {
174	      ...process.env,
175	      PATH: `${proxyRoot};${process.env.PATH ?? ""}`,
176	      SKILL_RAILS_EVAL_REAL_NODE: process.execPath,
177	      SKILL_RAILS_EVAL_PROJECT_ROOT: projectRoot,
178	    },
179	    statePath: resolve(projectRoot, ".skill-rails-next/evaluation-response-loss.json"),
180	  };
181	}
182	
183	async function run(options, command) {
184	  if (command.length === 0) throw new Error("HOST_COMMAND_REQUIRED");
185	  const scene = options.scene;
186	  const projectRoot = resolve(options["project-root"] ?? "");
187	  const receiptPath = resolve(options.receipt ?? "");
188	  if (!scene || !options["project-root"] || !options.receipt) throw new Error("SCENE_PROJECT_ROOT_RECEIPT_REQUIRED");
189	  const outputPath = resolve(projectRoot, "pilot/verification.md");
190	  const outputBefore = await fileObservation(outputPath);
191	  const initialCount = await exchangeCount(projectRoot);
192	  const timeoutMs = Number(options["watch-timeout-ms"] ?? 120000);
193	  const startedAt = new Date().toISOString();
194	  const responseLoss = await responseLossEnvironment(scene, projectRoot);
195	  const hostPromise = runProcess(command[0], command.slice(1), { cwd: projectRoot, env: responseLoss.env });
196	  let injected = null;
197	  let injectionError = null;
198	  try {
199	    injected = await injectAfterPrepare(scene, projectRoot, initialCount, timeoutMs);
200	  } catch (error) {
201	    injectionError = error instanceof Error ? error.message : String(error);
202	  }
203	  const host = await hostPromise;
204	  const sanitizedStdout = sanitizeHostStream(host.stdout);
205	  const receipt = {
206	    schemaVersion: 1,
207	    phase: "host-captured",
208	    scene,
209	    startedAt,
210	    projectRoot,
211	    command,
212	    hostExitCode: host.code,
213	    hostSignal: host.signal,
214	    wallClockMs: host.wallClockMs,
215	    injection: injected,
216	    injectionError,
217	    outputBefore,
218	    outputAfter: await fileObservation(outputPath),
219	    responseLossProxy: responseLoss.statePath ? {
220	      state: await fileObservation(responseLoss.statePath),
221	      details: (await fileObservation(responseLoss.statePath)).exists ? JSON.parse(await readFile(responseLoss.statePath, "utf8")) : null,
222	    } : null,
223	    stdout: { bytes: sanitizedStdout.bytes.length, sha256: sha256(sanitizedStdout.bytes), utf8: sanitizedStdout.bytes.toString("utf8"), redactions: sanitizedStdout.redactions },
224	    stderr: { bytes: host.stderr.length, sha256: sha256(host.stderr), utf8: host.stderr.toString("utf8") },
225	    interpretation: null,
226	    claimPolicy: "Captured process and filesystem facts are observed; semantic acceptance and causality require review and remain null until interpreted.",
227	  };
228	  await mkdir(dirname(receiptPath), { recursive: true });
229	  await writeFile(receiptPath, `${JSON.stringify(receipt, null, 2)}\n`, "utf8");
230	  process.stdout.write(`${JSON.stringify({ receiptPath, hostExitCode: host.code, outputAfter: receipt.outputAfter })}\n`);
231	  if (host.code !== 0 || injectionError) process.exitCode = 1;
232	}
233	
234	async function sanitizeReceipt(options) {
235	  if (!options.receipt) throw new Error("RECEIPT_REQUIRED");
236	  const receiptPath = resolve(options.receipt);
237	  const receipt = JSON.parse(await readFile(receiptPath, "utf8"));
238	  if (typeof receipt.stdout?.utf8 !== "string") throw new Error("CAPTURE_STDOUT_MISSING");
239	  const sanitized = sanitizeHostStream(Buffer.from(receipt.stdout.utf8, "utf8"));
240	  receipt.stdout = { bytes: sanitized.bytes.length, sha256: sha256(sanitized.bytes), utf8: sanitized.bytes.toString("utf8"), redactions: (receipt.stdout.redactions ?? 0) + sanitized.redactions };
241	  await writeFile(receiptPath, `${JSON.stringify(receipt, null, 2)}\n`, "utf8");
242	  process.stdout.write(`${JSON.stringify({ receiptPath, redactions: sanitized.redactions, stdout: { bytes: receipt.stdout.bytes, sha256: receipt.stdout.sha256 } })}\n`);
243	}
244	
245	const [action, ...rest] = process.argv.slice(2);
246	const { options, command } = parseArguments(rest);
247	if (action === "materialize") await materialize(options);
248	else if (action === "run") await run(options, command);
249	else if (action === "sanitize") await sanitizeReceipt(options);
250	else throw new Error("Usage: harness.mjs materialize ... | run ... -- <host command> | sanitize --receipt <capture>");
251

