import { test } from "node:test";
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const rendererPath = resolve(dirname(fileURLToPath(import.meta.url)), "../domains/natural-language-pilot/targets/verify/renderer.mjs");

const answer = {
  schemaVersion: 1,
  cardId: "bookmark-storage",
  verdict: "unproven",
  summary: "Targeted renderer label evidence.",
  checks: [{ name: "label check", outcome: "unproven", evidence: [] }],
  unknowns: [],
};

function render(currentOutput, validatedAnswer) {
  return new Promise((completion, rejection) => {
    const child = spawn(process.execPath, [rendererPath], { windowsHide: true, stdio: ["pipe", "pipe", "pipe"] });
    const stdout = [];
    const stderr = [];
    child.stdout.on("data", (chunk) => stdout.push(chunk));
    child.stderr.on("data", (chunk) => stderr.push(chunk));
    child.once("error", rejection);
    child.once("close", (code) => completion({ code, stdout: Buffer.concat(stdout).toString("utf8"), stderr: Buffer.concat(stderr).toString("utf8") }));
    child.stdin.end(JSON.stringify({ schemaVersion: 1, currentOutputBase64: Buffer.from(currentOutput, "utf8").toString("base64"), validatedAnswer }));
  });
}

test("rendered record labels the summary line exactly Finding:", async () => {
  const result = await render("", answer);
  assert.equal(result.code, 0, result.stderr);
  assert.match(result.stdout, /^Finding: Targeted renderer label evidence\.$/m);
  assert.doesNotMatch(result.stdout, /^Summary:/m);
});

test("encoded answer keeps the semantic summary field unchanged", async () => {
  const result = await render("", answer);
  assert.equal(result.code, 0, result.stderr);
  const marker = result.stdout.match(/^<!-- skill-rails-next:verify-record:([A-Za-z0-9_-]+) -->$/m);
  assert.ok(marker, "rendered record marker missing");
  const decoded = JSON.parse(Buffer.from(marker[1], "base64url").toString("utf8"));
  assert.equal(decoded.summary, answer.summary);
  assert.ok(!("finding" in decoded));
});

test("re-rendering the same answer over its own output is stable", async () => {
  const first = await render("", answer);
  assert.equal(first.code, 0, first.stderr);
  const second = await render(first.stdout, answer);
  assert.equal(second.code, 0, second.stderr);
  assert.equal(second.stdout, first.stdout);
});

